// Which of the owner's pool champions to play into one lane opponent (2026-11-23; ranking fixed
// 2026-11-24). Data: poolMatchups.js, generated by helpers/gen-pool-matchups.mjs. Tests:
// node helpers/test-pool-pick.mjs
//
// Ranks by the Iron+Bronze win rate (the owner's bracket) among the champions with MIN_GAMES
// games there; the others come back in `thin` and are shown after, marked as few games. It used to
// switch the whole ranking to Emerald+ whenever ANY option lacked low-elo games: into Singed,
// Pantheon's 121 games made it recommend Volibear (51.8% Emerald+) although he wins 41.3% in
// Iron+Bronze, behind Mordekaiser's 44.9%. Emerald+ is used only when no option has enough
// low-elo games, and `fewGames` says the ranking rests on thin data either way. A champion with
// under FLOOR games in the bracket used is left out: a 1-game 100% is not a pick.
//
// Two options are `close` when the gap is under CLOSE points or under 2 standard errors (the
// owner's rule for win rates), so a small-sample gap is not sold as a clear pick. `allLose` is
// set when the best option is under 50%.
import { POOL_MATCHUPS } from "./poolMatchups.js";

const MIN_GAMES = 150, FLOOR = 30, CLOSE = 1.5;
const GAMES = { lwr: "ln", hwr: "hn" };

const has = (r, key, min) => r[key] != null && r[GAMES[key]] >= min;
const byRate = (key) => (a, b) => b[key] - a[key];

// Two standard errors of the gap between two win rates, in points.
function twoSe(a, b, key) {
  const v = (r) => { const p = r[key] / 100; return (p * (1 - p)) / Math.max(1, r[GAMES[key]]); };
  return 200 * Math.sqrt(v(a) + v(b));
}

export function poolPick(role, foe, exclude = new Set(), data = POOL_MATCHUPS) {
  const rows = Object.entries(data[role]?.[foe] || {})
    .filter(([dd]) => !exclude.has(dd))
    .map(([dd, [lwr, ln, hwr, hn]]) => ({ dd, lwr, ln, hwr, hn }));
  if (rows.length === 0) return null;

  // Your bracket with enough games, else Emerald+, else either with at least FLOOR games (flagged).
  // Under FLOOR games a rate is noise: such a champion is neither ranked nor listed.
  const tiers = [["lwr", MIN_GAMES], ["hwr", MIN_GAMES], ["lwr", FLOOR], ["hwr", FLOOR]];
  const i = tiers.findIndex(([k, min]) => rows.some((r) => has(r, k, min)));
  if (i < 0) return null;
  const [key, min] = tiers[i];
  const ranked = rows.filter((r) => has(r, key, min)).sort(byRate(key));
  const thin = rows.filter((r) => !ranked.includes(r) && has(r, key, FLOOR)).sort(byRate(key));
  const fewGames = i > 0;

  const [a, b] = ranked;
  const close = !!b && a[key] - b[key] < Math.max(CLOSE, twoSe(a, b, key));
  return { bracket: key === "lwr" ? "Iron–Bronze" : "Emerald+", key, ranked, thin, close, fewGames, allLose: a[key] < 50 };
}

// The pool champions to recommend: the best, plus the runner-up when the gap is close. None when
// every option loses (2026-11-25): into Illaoi with Mordekaiser banned, 0.23.2.3 told the owner to
// "Play Volibear" at 42% and he lost; the strip now sends him to the Counters row instead.
export function poolLead(pick) {
  if (!pick || pick.allLose) return [];
  const [best, second] = pick.ranked;
  return pick.close && second ? [best.dd, second.dd] : [best.dd];
}
